BEGIN
  FOREACH color IN ARRAY ARRAY['445566','5A245A','003F88','767676','777777','FFFFFF','FFFF00'] LOOP
    candidate := jsonb_set(layout, ARRAY['templates','wide','elements','0','style','color'], to_jsonb(color));
    IF color IN ('445566','5A245A','003F88','767676') THEN
      PERFORM public.validate_ticket_layout(candidate);
    ELSE
      BEGIN
        PERFORM public.validate_ticket_layout(candidate);
        RAISE EXCEPTION 'Expected low-contrast color rejection' USING ERRCODE='XX000';
      EXCEPTION WHEN raise_exception THEN NULL; END;
    END IF;
  END LOOP;
END;
$test$;
ROLLBACK;
